package com.epsilon.cfr.benchmark;

import ai.djl.Device;
import com.epsilon.cfr.data.CfrReplayStore;
import com.epsilon.cfr.data.CfrSampleId;
import com.epsilon.cfr.data.CfrTrainingRow;
import com.epsilon.cfr.data.LogWeightedReplay;
import com.epsilon.cfr.model.CfrModel;
import com.epsilon.util.SeedMixer;
import com.google.gson.GsonBuilder;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.SplittableRandom;

/** 不変の既存リプレイを使い、再構築を計測外へ分離して学習区間だけを比較する診断実行。 */
public final class ExistingReplayBenchmark {
  public static void main(String[] args) throws Exception {
    if (args.length != 4) throw new IllegalArgumentException("CHECKPOINT REPLAY OUTPUT SAMPLING");
    Path checkpoint = Path.of(args[0]), replayPath = Path.of(args[1]), output = Path.of(args[2]);
    String sampling = args[3];
    if (!sampling.equals("weighted") && !sampling.equals("uniform-distinct"))
      throw new IllegalArgumentException("Unknown sampling mode");
    Files.createDirectory(output);
    var report = new LinkedHashMap<String, Object>();
    report.put("checkpoint", checkpoint.toString());
    report.put("replay", replayPath.toString());
    report.put("sampling", sampling);
    report.put("batch", 1024);
    report.put("seed", 20261008);
    report.put("checkpointEveryUpdates", 32);
    report.put("timingScope", "Replay sampled on every step; model.train includes observation"
        + " decode/packing, forward/backward and one clipped AdamW update. Checkpoint save every"
        + " 32 steps and final save/GPU completion included. Model/replay load and warmup excluded."
        + " Reuses the exact existing immutable replay, with no corpus reconstruction or shape diagnostics.");
    long start = System.nanoTime();
    try (var replay = CfrReplayStore.loadGeneration(replayPath, "performance-benchmark", 1);
        var model = CfrModel.loadTraining(checkpoint, Device.gpu(0))) {
      report.put("loadSeconds", seconds(start));
      report.put("modelConfig", model.config());
      report.put("role", model.role());
      var sampler = model.role() == CfrModel.Role.REGRET ? replay.regretSampler() : replay.averageSampler();
      report.put("replayWeights", sampler.metrics());
      report.put("warmup", window(model, sampler, output.resolve("warmup"), sampling, 8, 0));
      report.put("measured", window(model, sampler, output.resolve("measured"), sampling,
          sampling.equals("weighted") ? 128 : 64, 8));
    }
    Files.writeString(output.resolve("result.json"), new GsonBuilder().setPrettyPrinting().create().toJson(report));
  }

  private static Map<String, Object> window(CfrModel model, LogWeightedReplay sampler,
      Path checkpoints, String sampling, int updates, int offset) throws Exception {
    Files.createDirectory(checkpoints);
    long started = System.nanoTime(), unique = 0, logical = 0;
    double samplingSeconds = 0, trainingSeconds = 0, savingSeconds = 0, loss = 0;
    var windowIds = new HashSet<CfrSampleId>();
    int saves = 0;
    for (int update = 0; update < updates; update++) {
      long start = System.nanoTime();
      var rows = sample(sampler, sampling,
          new SplittableRandom(SeedMixer.derive(20261008, 0x44524157L, offset + update)));
      samplingSeconds += seconds(start);
      start = System.nanoTime();
      var metrics = model.train(rows);
      trainingSeconds += seconds(start);
      loss += metrics.loss();
      logical += metrics.samples();
      var ids = new HashSet<CfrSampleId>();
      for (CfrTrainingRow row : rows) ids.add(row.id());
      unique += ids.size();
      windowIds.addAll(ids);
      if ((update + 1) % 32 == 0 || update + 1 == updates) {
        start = System.nanoTime();
        model.saveTraining(checkpoints.resolve(String.format(java.util.Locale.ROOT, "%06d", update + 1)));
        savingSeconds += seconds(start);
        saves++;
      }
    }
    double elapsed = seconds(started);
    var report = new LinkedHashMap<String, Object>();
    report.put("elapsedSeconds", elapsed);
    report.put("samplingAndPayloadDecodeSeconds", samplingSeconds);
    report.put("trainCallIncludingObservationDecodeSeconds", trainingSeconds);
    report.put("checkpointSaveAndSynchronizationSeconds", savingSeconds);
    report.put("instrumentationAndLoopSeconds", Math.max(0, elapsed - samplingSeconds - trainingSeconds - savingSeconds));
    report.put("updates", updates);
    report.put("checkpointSaves", saves);
    report.put("logicalSamples", logical);
    report.put("uniqueProcessedRows", unique);
    report.put("distinctRowsAcrossWindow", windowIds.size());
    report.put("logicalSamplesPerSecond", logical / elapsed);
    report.put("uniqueProcessedRowsPerSecond", unique / elapsed);
    report.put("updatesPerSecond", updates / elapsed);
    report.put("meanLoss", loss / updates);
    return report;
  }

  private static List<CfrTrainingRow> sample(LogWeightedReplay sampler, String sampling, SplittableRandom random) {
    if (sampling.equals("weighted")) return sampler.sample(1024, random);
    var positions = new HashMap<Integer, Integer>();
    var rows = new ArrayList<CfrTrainingRow>(1024);
    for (int picked = 0; picked < 1024; picked++) {
      int last = sampler.size() - picked - 1;
      int selected = random.nextInt(last + 1);
      int index = positions.getOrDefault(selected, selected);
      if (selected != last) positions.put(selected, positions.getOrDefault(last, last));
      positions.remove(last);
      rows.add(sampler.rowAt(index));
    }
    return List.copyOf(rows);
  }

  private static double seconds(long start) { return (System.nanoTime() - start) / 1e9; }
}

