package com.epsilon.cfr.model;

import ai.djl.Device;
import ai.djl.Model;
import ai.djl.ndarray.types.DataType;
import ai.djl.ndarray.types.Shape;
import com.epsilon.cfr.data.CfrReplayStore;
import com.epsilon.cfr.data.CfrTrainingRow;
import com.epsilon.cfr.data.LogWeightedReplay;
import com.epsilon.config.settings.DecisionComputePrecision;
import com.epsilon.nano.ai.decision.input.DecisionInputSchema;
import com.epsilon.network.NetworkDevices;
import com.epsilon.network.NetworkRuntime;
import com.epsilon.training.DataParallelGroup;
import com.epsilon.util.SeedMixer;
import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import java.io.BufferedInputStream;
import java.io.DataInputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.SplittableRandom;
import java.util.TreeMap;

/** 保存済みの同じ重み・教師行で、単行抽選と重複読み込みを集約した一括抽選を比較する診断専用実行。 */
public final class CfrReplayBatchComparison {
  private static final Gson JSON = new GsonBuilder().setPrettyPrinting().create();

  private record Metadata(
      int version,
      String architecture,
      String inputSchema,
      CfrModel.Role role,
      CfrModelConfig config,
      long updates,
      boolean trainingState) {}

  public static void main(String[] args) throws Exception {
    if (args.length < 3 || args.length > 11)
      throw new IllegalArgumentException(
          "CHECKPOINT REPLAY_DIR OUTPUT [sampling=uniform-distinct]"
              + " [mode=local] [updates=6] [batch=1024] [microA=1024] [microB=1024]"
              + " [seed=20261008] [sampleOffset=0]");
    Path checkpoint = Path.of(args[0]).toAbsolutePath();
    Path replayPath = Path.of(args[1]).toAbsolutePath();
    Path output = Path.of(args[2]).toAbsolutePath();
    String sampling = argument(args, 3, "uniform-distinct");
    String mode = argument(args, 4, "local");
    int steps = Integer.parseInt(argument(args, 5, "6"));
    int batch = Integer.parseInt(argument(args, 6, "1024"));
    int microA = Integer.parseInt(argument(args, 7, "1024"));
    int microB = Integer.parseInt(argument(args, 8, "1024"));
    long seed = Long.parseLong(argument(args, 9, "20261008"));
    int offset = Integer.parseInt(argument(args, 10, "0"));
    if (!(sampling.equals("weighted") || sampling.equals("uniform-distinct"))
        || !(mode.equals("local") || mode.equals("cumulative"))
        || steps < 1
        || batch < 1
        || microA < 1
        || microB < 1
        || microB > batch
        || offset < 0) throw new IllegalArgumentException("Invalid comparison arguments");
    Metadata metadata =
        JSON.fromJson(Files.readString(checkpoint.resolve("model.json")), Metadata.class);
    if (metadata == null
        || metadata.version() != 3
        || !CfrNetwork.ARCHITECTURE.equals(metadata.architecture())
        || !DecisionInputSchema.fingerprint().equals(metadata.inputSchema())
        || metadata.role() == null
        || metadata.config() == null
        || !metadata.trainingState()
        || metadata.updates() < 0)
      throw new IllegalArgumentException("Expected a current CFR training checkpoint");
    if (metadata.config().computePrecision() != DecisionComputePrecision.BFLOAT16)
      throw new IllegalArgumentException("Expected BFLOAT16 checkpoint for existing BF16 criteria");
    if (!sampling.equals("weighted") || microA != microB)
      throw new IllegalArgumentException("Comparison requires weighted sampling and the same microbatch limit");
    Files.createDirectories(output.getParent());
    Files.createDirectory(output);
    NetworkRuntime.initialize();
    Device device = Device.gpu(Integer.getInteger("epsilon.cfr.device", 0));
    var report = new LinkedHashMap<String, Object>();
    report.put("checkpoint", checkpoint.toString());
    report.put("replay", replayPath.toString());
    report.put("role", metadata.role());
    report.put("sourceConfig", metadata.config());
    report.put("sampling", sampling);
    report.put("comparison", "scalar repeated loading versus batch-local immutable row reuse; same tree walk and learner");
    report.put("mode", mode);
    report.put("batch", batch);
    report.put("microA", microA);
    report.put("microB", microB);
    report.put("seed", seed);
    report.put("sampleOffset", offset);
    report.put("criteriaSource", "CfrBatchingTest and CfrMultiplicityLearningTest BF16 criteria");
    report.put(
        "timingScope",
        "Diagnostic train+GPU completion only. Parameter readbacks, optimizer"
            + " synchronization and sampling are outside these times. No throughput conclusion.");
    List<Object> comparisons = new ArrayList<>();
    report.put("steps", comparisons);
    boolean passed = true;
    Path optimizer = output.resolve("comparison-optimizer.bin");
    try (var replay = CfrReplayStore.loadGeneration(replayPath, "performance-benchmark", 1);
        var baseline = new Fixture(checkpoint, metadata, microA, device);
        var candidate = new Fixture(checkpoint, metadata, microB, device)) {
      var sampler =
          metadata.role() == CfrModel.Role.REGRET
              ? replay.regretSampler()
              : replay.averageSampler();
      report.put("replayWeights", sampler.metrics());
      var original = snapshot(baseline.network);
      requireSame(original, snapshot(candidate.network));
      for (int step = 1; step <= steps; step++) {
        if (mode.equals("local") && step > 1) {
          baseline.learner.saveOptimizer(optimizer);
          candidate.learner.synchronizeParameters();
          DataParallelGroup.copyParameters(baseline.model, candidate.model);
          candidate.learner.loadOptimizer(optimizer);
        }
        var origin = mode.equals("local") ? snapshot(baseline.network) : original;
        if (mode.equals("local")) requireSame(origin, snapshot(candidate.network));
        long drawSeed = SeedMixer.derive(seed, 0x44524157L, offset + step - 1);
        var scalarRandom = new SplittableRandom(drawSeed);
        var batchRandom = new SplittableRandom(drawSeed);
        List<CfrTrainingRow> rows = new ArrayList<>(batch);
        for (int index = 0; index < batch; index++) rows.add(sampler.sample(scalarRandom));
        List<CfrTrainingRow> batchedRows = sampler.sample(batch, batchRandom);
        for (int index = 0; index < batch; index++) {
          if (!rows.get(index).contentEquals(batchedRows.get(index)))
            throw new AssertionError("Sampling content differs at " + index);
        }
        if (scalarRandom.nextLong() != batchRandom.nextLong())
          throw new AssertionError("Sampling random consumption differs");
        var result = new LinkedHashMap<String, Object>();
        result.put("step", step);
        result.put("sampleUpdate", offset + step - 1);
        result.put("buckets", buckets(rows, microA, microB));
        long start = System.nanoTime();
        var a = baseline.learner.train(rows, metadata.updates() + step);
        baseline.learner.awaitModelReady();
        result.put("microATrainAndAwaitSeconds", (System.nanoTime() - start) / 1e9);
        start = System.nanoTime();
        var b = candidate.learner.train(batchedRows, metadata.updates() + step);
        candidate.learner.awaitModelReady();
        result.put("microBTrainAndAwaitSeconds", (System.nanoTime() - start) / 1e9);
        result.put("microAMetrics", a);
        result.put("microBMetrics", b);
        List<String> failures = new ArrayList<>();
        check(a.samples() == rows.size() && b.samples() == rows.size(), "sample count", failures);
        check(Math.abs(b.loss() - a.loss()) <= 2e-4 + .01 * Math.abs(a.loss()), "loss", failures);
        check(
            Math.abs(b.gradientNorm() - a.gradientNorm()) <= 2e-4 + .02 * a.gradientNorm(),
            "gradientNorm",
            failures);
        var parameters = new Difference();
        var updates = new Difference();
        double stateUpdateSquared = 0;
        double maxElementDifference = 0;
        double elementTolerance =
            .5 * (mode.equals("local") ? 1 : step) * metadata.config().learningRate();
        var wanted = snapshot(baseline.network);
        var actual = snapshot(candidate.network);
        for (var entry : wanted.entrySet()) {
          float[] expected = entry.getValue(), found = actual.get(entry.getKey());
          float[] before = origin.get(entry.getKey());
          parameters.add(found, expected, null);
          updates.add(found, expected, before);
          for (int i = 0; i < found.length; i++) {
            maxElementDifference =
                Math.max(maxElementDifference, Math.abs((double) found[i] - expected[i]));
            if (entry.getKey().contains("stateEncoder")) {
              double change = (double) expected[i] - before[i];
              stateUpdateSquared += change * change;
            }
          }
        }
        check(maxElementDifference <= elementTolerance, "parameter element maximum", failures);
        parameters.check(5e-4, .99999, "parameters", failures);
        updates.check(.03, .999, "AdamW update", failures);
        result.put("lossAbsoluteDifference", Math.abs(b.loss() - a.loss()));
        result.put("gradientNormAbsoluteDifference", Math.abs(b.gradientNorm() - a.gradientNorm()));
        result.put("parameters", parameters.summary());
        result.put("adamWUpdate", updates.summary());
        result.put("stateEncoderUpdateL2", Math.sqrt(stateUpdateSquared));
        result.put("maxElementDifference", maxElementDifference);
        result.put("elementTolerance", elementTolerance);
        result.put("failures", failures);
        result.put("passed", failures.isEmpty());
        comparisons.add(result);
        passed &= failures.isEmpty();
        report.put("passed", passed);
        Files.writeString(output.resolve("result.json"), JSON.toJson(report));
        System.out.println(
            "CFR replay batch comparison role="
                + metadata.role()
                + " mode="
                + mode
                + " sampling="
                + sampling
                + " step="
                + step
                + " passed="
                + failures.isEmpty()
                + " updateRelativeL2="
                + updates.relativeError()
                + " updateCosine="
                + updates.cosine());
      }
    } finally {
      Files.deleteIfExists(optimizer);
    }
    if (!passed)
      throw new AssertionError(
          "Microbatch comparison exceeded existing BF16 criteria; see result.json");
  }

  private static String argument(String[] args, int index, String fallback) {
    return args.length > index ? args[index] : fallback;
  }

  private static List<CfrTrainingRow> sample(
      LogWeightedReplay sampler, String sampling, int count, SplittableRandom random) {
    if (sampling.equals("weighted")) return sampler.sample(count, random);
    if (count > sampler.size()) throw new IllegalArgumentException("Too few distinct replay rows");
    Map<Integer, Integer> positions = new HashMap<>();
    List<CfrTrainingRow> rows = new ArrayList<>(count);
    for (int picked = 0; picked < count; picked++) {
      int last = sampler.size() - picked - 1;
      int selected = random.nextInt(last + 1);
      int index = positions.getOrDefault(selected, selected);
      if (selected != last) positions.put(selected, positions.getOrDefault(last, last));
      positions.remove(last);
      rows.add(sampler.rowAt(index));
    }
    return List.copyOf(rows);
  }

  private static Map<String, Object> buckets(List<CfrTrainingRow> rows, int microA, int microB) {
    Map<String, Integer> counts = new TreeMap<>();
    for (var entry : CfrSampleMultiplicity.aggregate(rows)) {
      var bucket = CfrObservationCodec.decode(entry.row().observation()).host().bucket();
      counts.merge(
          bucket.legalActionCapacity() + "x" + bucket.actionTransitionCapacity(), 1, Integer::sum);
    }
    Map<String, Object> result = new TreeMap<>();
    counts.forEach(
        (key, count) ->
            result.put(
                key,
                Map.of(
                    "uniqueRows",
                    count,
                    "microASizes",
                    sizes(count, microA),
                    "microBSizes",
                    sizes(count, microB))));
    return result;
  }

  private static List<Integer> sizes(int count, int micro) {
    List<Integer> sizes = new ArrayList<>();
    for (int from = 0; from < count; from += micro) sizes.add(Math.min(count - from, micro));
    return sizes;
  }

  private static Map<String, float[]> snapshot(CfrNetwork network) {
    Map<String, float[]> values = new LinkedHashMap<>();
    for (var entry : network.getParameters())
      values.put(entry.getKey(), entry.getValue().getArray().toFloatArray());
    return values;
  }

  private static void requireSame(Map<String, float[]> expected, Map<String, float[]> actual) {
    if (!expected.keySet().equals(actual.keySet()))
      throw new AssertionError("Parameter names differ");
    for (var entry : expected.entrySet())
      if (!java.util.Arrays.equals(entry.getValue(), actual.get(entry.getKey())))
        throw new AssertionError("Comparison starts from different parameters: " + entry.getKey());
  }

  private static void check(boolean value, String message, List<String> failures) {
    if (!value) failures.add(message);
  }

  private static final class Difference {
    double squaredError, squaredActual, squaredExpected, dot;

    void add(float[] actual, float[] expected, float[] origin) {
      if (actual.length != expected.length) throw new AssertionError("Parameter shape differs");
      for (int index = 0; index < actual.length; index++) {
        double initial = origin == null ? 0 : origin[index];
        double a = actual[index] - initial, b = expected[index] - initial;
        squaredError += (a - b) * (a - b);
        squaredActual += a * a;
        squaredExpected += b * b;
        dot += a * b;
      }
    }

    double relativeError() {
      return Math.sqrt(squaredError / Math.max(1e-30, squaredExpected));
    }

    double cosine() {
      return dot / Math.sqrt(squaredActual * squaredExpected);
    }

    void check(
        double relativeTolerance, double minimumCosine, String label, List<String> failures) {
      CfrReplayBatchComparison.check(
          relativeError() <= relativeTolerance, label + " relativeL2", failures);
      CfrReplayBatchComparison.check(cosine() >= minimumCosine, label + " cosine", failures);
    }

    Map<String, Object> summary() {
      var result = new LinkedHashMap<String, Object>();
      result.put("relativeL2", relativeError());
      result.put("cosine", Double.isFinite(cosine()) ? cosine() : null);
      result.put("absoluteL2", Math.sqrt(squaredError));
      result.put("microAL2", Math.sqrt(squaredExpected));
      result.put("microBL2", Math.sqrt(squaredActual));
      return result;
    }
  }

  private static final class Fixture implements AutoCloseable {
    final Model model;
    final CfrNetwork network;
    final CfrLearner learner;

    Fixture(Path checkpoint, Metadata metadata, int micro, Device device) throws Exception {
      var source = metadata.config();
      var config =
          new CfrModelConfig(
              source.hiddenSize(),
              micro,
              source.learningRate(),
              source.weightDecay(),
              source.gradientClip(),
              source.seed(),
              source.inferenceBatchSize(),
              source.computePrecision(),
              source.tensorTransfer(),
              source.utilityProfile());
      model = Model.newInstance("cfr-microbatch-comparison", device, "PyTorch");
      network = new CfrNetwork(config);
      model.setBlock(network);
      network.initialize(model.getNDManager(), DataType.FLOAT32, new Shape(1, 1));
      try (var input =
          new DataInputStream(
              new BufferedInputStream(Files.newInputStream(checkpoint.resolve("weights.bin"))))) {
        network.loadParameters(model.getNDManager(), input);
        if (input.read() != -1) throw new IllegalArgumentException("Trailing CFR weights");
      }
      for (var parameter : network.getParameters().values()) {
        parameter.freeze(false);
        parameter.getArray().setRequiresGradient(true);
      }
      learner = new CfrLearner(config, metadata.role(), model, network, NetworkDevices.of(device));
      learner.loadOptimizer(checkpoint.resolve("optimizer.bin"));
    }

    @Override
    public void close() {
      learner.close();
      model.close();
    }
  }
}

