package com.epsilon.cfr.model;

import ai.djl.Device;
import ai.djl.Model;
import ai.djl.ndarray.types.DataType;
import ai.djl.ndarray.types.Shape;
import ai.djl.training.optimizer.Optimizer;
import ai.djl.training.tracker.Tracker;
import com.epsilon.network.NetworkRuntime;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonParser;
import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;
import java.util.zip.*;

/** 保存済みの学習状態を変更せず、重みとAdamW状態の保存時間を分けて測る診断。 */
public final class CheckpointSaveProbe {
  public static void main(String[] args) throws Exception {
    if (args.length != 2) throw new IllegalArgumentException("CHECKPOINT OUTPUT");
    Path source = Path.of(args[0]), output = Path.of(args[1]); Files.createDirectory(output);
    var json = new GsonBuilder().setPrettyPrinting().create();
    var metadata = JsonParser.parseString(Files.readString(source.resolve("model.json"))).getAsJsonObject();
    var config = json.fromJson(metadata.get("config"), CfrModelConfig.class);
    NetworkRuntime.initialize();
    var report = new LinkedHashMap<String,Object>();
    report.put("checkpoint", source.toString()); report.put("warmup", 1); report.put("repeats", 5);
    report.put("scope", "Immutable trained model and optimizer state; production weights saveParameters with buffered output and optimizer.saveState unchanged. Includes each component's GPU readback, encoding and filesystem writes; no model/replay loading or training. NPZ level timings separately recompress identical already-host-resident NPY entries to memory; diagnostic only.");
    var measurements = new ArrayList<Object>(); report.put("measurements", measurements);
    try (Model model = Model.newInstance("cfr-checkpoint-save-probe", Device.gpu(0), "PyTorch")) {
      var network = new CfrNetwork(config); model.setBlock(network);
      network.initialize(model.getNDManager(), DataType.FLOAT32, new Shape(1,1));
      try (var in = new DataInputStream(new BufferedInputStream(Files.newInputStream(source.resolve("weights.bin"))))) { network.loadParameters(model.getNDManager(), in); }
      var optimizer = Optimizer.adamW().optLearningRateTracker(Tracker.fixed(config.learningRate())).optWeightDecays(config.weightDecay()).build();
      optimizer.loadState(model.getNDManager(), source.resolve("optimizer.bin"));
      for (int step = -1; step < 5; step++) {
        Path weights = output.resolve("weights-" + step + ".bin"), state = output.resolve("optimizer-" + step + ".bin");
        long start = System.nanoTime();
        try (var out = new DataOutputStream(new BufferedOutputStream(Files.newOutputStream(weights)))) { network.saveParameters(out); }
        double weightsSeconds = seconds(start); start = System.nanoTime(); optimizer.saveState(state); double optimizerSeconds = seconds(start);
        if (step >= 0) measurements.add(Map.of("weightsSeconds", weightsSeconds, "optimizerSeconds", optimizerSeconds, "weightsBytes", Files.size(weights), "optimizerBytes", Files.size(state)));
      }
      report.put("hostNpzCompression", compression(output.resolve("optimizer-4.bin")));
    }
    Files.writeString(output.resolve("result.json"), json.toJson(report));
    System.out.println(json.toJson(report));
  }
  private static List<Object> compression(Path checkpoint) throws Exception {
    byte[] payload;
    try (var in = new DataInputStream(new BufferedInputStream(Files.newInputStream(checkpoint)))) {
      if (!in.readUTF().equals("DJL_OPTIMIZER_STATE") || in.readInt() != 1) throw new IllegalArgumentException("Unexpected optimizer format");
      in.readUTF(); in.readInt(); in.readInt(); int count = in.readInt();
      for (int i = 0; i < count; i++) { in.readUTF(); in.readInt(); }
      payload = in.readNBytes(in.readInt()); if (in.read() != -1) throw new IllegalArgumentException("Trailing optimizer data");
    }
    var entries = new LinkedHashMap<String,byte[]>();
    try (var zip = new ZipInputStream(new ByteArrayInputStream(payload))) {
      for (ZipEntry entry; (entry = zip.getNextEntry()) != null;) entries.put(entry.getName(), zip.readAllBytes());
    }
    long rawBytes = entries.values().stream().mapToLong(a -> a.length).sum();
    var results = new ArrayList<Object>();
    for (int level : new int[] {-1, 1, 0}) {
      double[] elapsed = new double[3]; int encodedBytes = 0;
      for (int repeat = -1; repeat < 3; repeat++) {
        long start = System.nanoTime();
        var buffer = new ByteArrayOutputStream((int)rawBytes + 1024);
        try (var zip = new ZipOutputStream(buffer)) {
          zip.setLevel(level);
          for (var entry : entries.entrySet()) { zip.putNextEntry(new ZipEntry(entry.getKey())); zip.write(entry.getValue()); zip.closeEntry(); }
        }
        if (repeat >= 0) elapsed[repeat] = seconds(start);
        byte[] encoded = buffer.toByteArray(); encodedBytes = encoded.length;
        try (var zip = new ZipInputStream(new ByteArrayInputStream(encoded))) {
          int count = 0;
          for (ZipEntry entry; (entry = zip.getNextEntry()) != null;) {
            if (!Arrays.equals(entries.get(entry.getName()), zip.readAllBytes())) throw new AssertionError("Compression changed NPY bytes"); count++;
          }
          if (count != entries.size()) throw new AssertionError("Compression changed entry count");
        }
      }
      results.add(Map.of("level", level, "seconds", elapsed, "meanSeconds", Arrays.stream(elapsed).average().orElseThrow(), "encodedBytes", encodedBytes, "rawNpyBytes", rawBytes, "entries", entries.size(), "roundtripExact", true));
    }
    return results;
  }
  private static double seconds(long start) { return (System.nanoTime() - start) / 1e9; }
}

