package com.epsilon.cfr.model;

import ai.djl.Device;
import ai.djl.Model;
import ai.djl.engine.Autocast;
import ai.djl.engine.Engine;
import ai.djl.ndarray.NDArray;
import ai.djl.ndarray.NDManager;
import ai.djl.ndarray.types.DataType;
import ai.djl.ndarray.types.Shape;
import ai.djl.pytorch.engine.PtEngine;
import ai.djl.pytorch.engine.PtEvent;
import ai.djl.training.ParameterStore;
import ai.djl.util.PairList;
import com.epsilon.cfr.data.CfrReplayStore;
import com.epsilon.cfr.data.CfrSampleId;
import com.epsilon.nano.ai.decision.input.DecisionBatchTransfer;
import com.epsilon.nano.ai.decision.input.DecisionDeviceBatch;
import com.epsilon.nano.ai.decision.runtime.EpsilonDecisionAutocast;
import com.epsilon.nano.ai.decision.training.EpsilonDecisionCheckpointManager;
import com.epsilon.nano.ai.model.EpsilonDecisionNetwork;
import com.epsilon.network.NetworkRuntime;
import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonParser;
import java.io.BufferedInputStream;
import java.io.DataInputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;

/** 保存済みの同じ盤面を使う計算量診断。教師、optimizer、学習品質を比較するものではない。 */
public final class MatchedBoardProbe {
  private static final Gson GSON = new GsonBuilder().setPrettyPrinting().create();

  private enum Mode {
    CFR_BOARD,
    NANO_ACTOR_VALUE
  }

  private record Row(CfrSampleId id, CfrObservationCodec.Decoded observation) {}

  private record Corpus(List<Row> rows, int replayRowsRead, int candidates) {}

  private record Step(double seconds, float loss) {}

  public static void main(String[] args) throws Exception {
    if (args.length < 4 || args.length > 10)
      throw new IllegalArgumentException(
          "CFR_CHECKPOINT NANO_CHECKPOINT REPLAY OUTPUT_JSON [BATCHES=113,512,1024]"
              + " [WARMUP=8] [REPEATS=15] [MODES=all]"
              + " [ACTION_CAPACITY=16] [TRANSITION_CAPACITY=1]");
    Path cfrCheckpoint = Path.of(args[0]), nanoCheckpoint = Path.of(args[1]);
    Path source = Path.of(args[2]), output = Path.of(args[3]);
    if (Files.exists(output))
      throw new IllegalArgumentException("Output already exists: " + output);
    int[] batches =
        Arrays.stream(
                args.length > 4 ? args[4].split(",") : new String[] {"113", "512", "1024"})
            .mapToInt(Integer::parseInt)
            .toArray();
    int warmup = integer(args, 5, 8), repeats = integer(args, 6, 15);
    List<Mode> modes =
        args.length <= 7 || args[7].equals("all")
            ? List.of(Mode.values())
            : Arrays.stream(args[7].split(",")).map(Mode::valueOf).toList();
    int actions = integer(args, 8, 16), transitions = integer(args, 9, 1);
    int largest = Arrays.stream(batches).max().orElseThrow();
    if (warmup < 0 || repeats < 1 || largest < 1)
      throw new IllegalArgumentException("Invalid measurement dimensions");
    Corpus corpus = corpus(source, largest, actions, transitions);
    var metadata =
        JsonParser.parseString(Files.readString(cfrCheckpoint.resolve("model.json")))
            .getAsJsonObject();
    CfrModelConfig config = GSON.fromJson(metadata.get("config"), CfrModelConfig.class);
    NetworkRuntime.initialize();
    Device device = Device.gpu(0);
    var engine = (PtEngine) Engine.getEngine("PyTorch");
    Map<String, Object> report = new LinkedHashMap<>();
    report.put("diagnosticOnly", true);
    report.put("cfrCheckpoint", cfrCheckpoint.toString());
    report.put("nanoCheckpoint", nanoCheckpoint.toString());
    report.put("replay", source.toString());
    report.put("replayRowsRead", corpus.replayRowsRead());
    report.put("eligibleRows", corpus.candidates());
    report.put("poolRows", corpus.rows().size());
    report.put("bucket", List.of(actions, transitions));
    report.put("warmup", warmup);
    report.put("repeats", repeats);
    report.put("cfrConfig", config);
    report.put(
        "timingScope",
        "Matched real CFR observations and identical resident DecisionDeviceBatch for both"
            + " networks. Fixed loaded weights; no optimizer, teacher, replay sampling, model"
            + " persistence or training-quality comparison. Each step includes graph construction,"
            + " forward and optionally backward, and an explicit GPU completion event. Gradient"
            + " clearing, shared board materialization/H2D, model load, corpus preparation and"
            + " final tensor cleanup are excluded. Nano sums actor branch/candidate/riichi and"
            + " value energies; CFR uses its candidate score energy. Both traverse the same Nano"
            + " board feature spine, with their own production output heads. Training precision"
            + " is taken from the CFR model configuration for both networks.");
    List<Map<String, Object>> measurements = new ArrayList<>();
    report.put("measurements", measurements);
    try (var stream = engine.newStream(device);
        var streamScope = stream.openScope();
        PtEvent event = stream.newEvent();
        Model cfrModel = Model.newInstance("cfr-matched-probe", device, "PyTorch");
        Model nanoModel = EpsilonDecisionCheckpointManager.load(nanoCheckpoint, device, false)) {
      CfrNetwork cfr = new CfrNetwork(config);
      cfrModel.setBlock(cfr);
      cfr.initialize(cfrModel.getNDManager(), DataType.FLOAT32, new Shape(1, 1));
      try (var weights =
          new DataInputStream(
              new BufferedInputStream(
                  Files.newInputStream(cfrCheckpoint.resolve("weights.bin"))))) {
        cfr.loadParameters(cfrModel.getNDManager(), weights);
        if (weights.read() != -1) throw new IllegalStateException("Trailing CFR weights");
      }
      EpsilonDecisionNetwork nano = (EpsilonDecisionNetwork) nanoModel.getBlock();
      for (Model model : List.of(cfrModel, nanoModel)) {
        for (var parameter : model.getBlock().getParameters().values()) {
          parameter.freeze(false);
          parameter.getArray().setRequiresGradient(true);
        }
      }
      report.put("nanoHiddenSize", nano.hiddenSize());
      report.put(
          "parameterCount", Map.of("cfr", parameters(cfrModel), "nano", parameters(nanoModel)));
      sync(event);
      for (int count : batches) {
        List<Row> selected = corpus.rows().subList(0, count);
        List<CfrObservationCodec.Decoded> rows = selected.stream().map(Row::observation).toList();
        try (NDManager resident = cfrModel.getNDManager().newSubManager()) {
          long prepareStart = System.nanoTime();
          var host = CfrObservationCodec.batch(rows);
          DecisionDeviceBatch batch =
              DecisionBatchTransfer.transferTrainingToDevice(resident, host);
          sync(event);
          double boardPreparationSeconds = seconds(prepareStart);
          for (boolean backward : new boolean[] {false, true}) {
            for (Mode mode : modes) {
              Model model = mode == Mode.NANO_ACTOR_VALUE ? nanoModel : cfrModel;
              for (int index = 0; index < warmup; index++)
                step(
                    mode, backward, model, cfr, nano, batch, resident, config, event);
              sync(event);
              long allocatedBefore = engine.getMemoryStats(device).getAllocatedBytes();
              engine.resetPeakMemoryStats(device);
              double[] elapsed = new double[repeats];
              long[] allocatedAfterStep = new long[repeats];
              float loss = Float.NaN;
              for (int index = 0; index < repeats; index++) {
                Step result =
                    step(
                        mode, backward, model, cfr, nano, batch, resident, config,
                        event);
                elapsed[index] = result.seconds();
                loss = result.loss();
                allocatedAfterStep[index] = engine.getMemoryStats(device).getAllocatedBytes();
              }
              double[] ordered = elapsed.clone();
              Arrays.sort(ordered);
              double median = ordered[ordered.length / 2];
              Map<String, Object> measurement = new LinkedHashMap<>();
              measurement.put("mode", mode.name());
              measurement.put("backward", backward);
              measurement.put("rows", count);
              measurement.put("seconds", elapsed);
              measurement.put("medianSeconds", median);
              measurement.put("medianRowsPerSecond", count / median);
              measurement.put("loss", loss);
              measurement.put("allocatedBeforeBytes", allocatedBefore);
              measurement.put("allocatedAfterStepBytes", allocatedAfterStep);
              measurement.put(
                  "peakAllocatedBytes", engine.getMemoryStats(device).getPeakAllocatedBytes());
              measurement.put(
                  "reservedAfterBytes", engine.getMemoryStats(device).getReservedBytes());
              measurement.put("firstSampleIds", selected.stream().limit(4).map(Row::id).toList());
              measurement.put("sharedBoardPreparationSeconds", boardPreparationSeconds);
              measurements.add(measurement);
              Files.writeString(output, GSON.toJson(report));
              System.out.printf(
                  "%s backward=%s batch=%d medianMs=%.3f rows/s=%.1f loss=%.9g%n",
                  mode, backward, count, median * 1000, count / median, loss);
            }
          }
        }
      }
    }
    report.put("complete", true);
    Files.writeString(output, GSON.toJson(report));
  }

  private static Step step(
      Mode mode,
      boolean backward,
      Model model,
      CfrNetwork cfr,
      EpsilonDecisionNetwork nano,
      DecisionDeviceBatch batch,
      NDManager resident,
      CfrModelConfig config,
      PtEvent event) {
    if (backward)
      for (var parameter : model.getBlock().getParameters().values()) {
        NDArray array = parameter.getArray();
        if (array.hasGradient()) {
          try (NDArray gradient = array.getGradient()) {
            gradient.fillI(0);
          }
        }
      }
    sync(event);
    long start = System.nanoTime();
    try (NDManager scope = resident.newSubManager();
        var collector = backward ? scope.getEngine().newGradientCollector() : null;
        var inference = backward ? null : scope.getEngine().newInferenceMode()) {
      NDArray objective;
      try (Autocast ignored =
          EpsilonDecisionAutocast.open(scope, config.precision(scope.getDevice()))) {
        // 入力をこの計算の有効範囲へ一時的に借り、入力から派生する中間テンソルも毎回解放する。
        scope.tempAttachAll(batch.inputs().toNDList().toArray(new NDArray[0]));
        scope.tempAttachAll(
            batch.categoricalSlab(),
            batch.numericSlab(),
            batch.playerMemoryPresentIndices(),
            batch.transitionPresentIndices());
        ParameterStore store = new ParameterStore(scope, true);
        if (mode == Mode.NANO_ACTOR_VALUE) {
          var output = nano.forwardWithDiagnostics(store, batch, true, new PairList<>());
          objective = energy(output.valueLogits(), scope);
          for (NDArray scores : output.policyScores().toNDList())
            objective = objective.add(energy(scores, scope));
        } else {
          objective = energy(cfr.scores(store, batch, true), scope);
        }
      }
      if (collector != null) collector.backward(objective);
      sync(event);
      double elapsed = seconds(start);
      float loss = objective.getFloat();
      if (!Float.isFinite(loss))
        throw new IllegalStateException("Nonfinite probe objective: " + mode);
      return new Step(elapsed, loss);
    }
  }

  private static NDArray energy(NDArray values, NDManager scope) {
    if (values.getDataType() != DataType.FLOAT32)
      values = values.add(scope.zeros(new Shape(1), DataType.FLOAT32));
    return values.square().mean();
  }

  private static Corpus corpus(Path directory, int count, int actions, int transitions)
      throws Exception {
    List<Row> candidates = new ArrayList<>();
    int read = 0;
    try (var replay = CfrReplayStore.loadGeneration(directory, "performance-benchmark", 1)) {
      var sampler = replay.regretSampler();
      for (int index = 0; index < sampler.size(); index++) {
        var row = sampler.rowAt(index);
        var observation = CfrObservationCodec.decode(row.observation());
        var bucket = observation.host().bucket();
        if (bucket.legalActionCapacity() == actions
            && bucket.actionTransitionCapacity() == transitions)
          candidates.add(new Row(row.id(), observation));
        read++;
        if (candidates.size() >= Math.max(4096, count)) break;
      }
    }
    if (candidates.size() < count)
      throw new IllegalArgumentException("Insufficient matching rows: " + candidates.size());
    Collections.shuffle(candidates, new Random(20261009));
    return new Corpus(List.copyOf(candidates.subList(0, count)), read, candidates.size());
  }

  private static long parameters(Model model) {
    return model.getBlock().getParameters().values().stream()
        .mapToLong(p -> p.getArray().size())
        .sum();
  }

  private static int integer(String[] args, int index, int fallback) {
    return args.length > index ? Integer.parseInt(args[index]) : fallback;
  }

  private static void sync(PtEvent event) {
    event.record();
    event.synchronize();
  }

  private static double seconds(long start) {
    return (System.nanoTime() - start) / 1e9;
  }
}

helper-src/com/epsilon/cfr/model/Optimiz.content:
package com.epsilon.cfr.model;

import ai.djl.Device;
import ai.djl.Model;
import ai.djl.ndarray.NDArray;
import ai.djl.ndarray.types.DataType;
import ai.djl.ndarray.types.Shape;
import ai.djl.training.optimizer.Optimizer;
import ai.djl.training.tracker.Tracker;
import com.epsilon.nano.ai.decision.training.EpsilonDecisionCheckpointManager;
import com.epsilon.nano.ai.model.EpsilonDecisionNetwork;
import com.epsilon.network.NetworkRuntime;
import com.epsilon.runtime.DecisionExecutionContext;
import com.epsilon.training.DataParallelGroup;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonParser;
import java.io.BufferedInputStream;
import java.io.DataInputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.function.Predicate;

/** 保存済みモデルへ一定勾配を与え、共通基盤の更新一回の固定費だけを測る診断。 */
public final class OptimizerFixedCostProbe {
  public static void main(String[] args) throws Exception {
    if (args.length != 4) throw new IllegalArgumentException("CFR_CHECKPOINT NANO_CHECKPOINT OUTPUT ORDER");
    Path cfrPath = Path.of(args[0]), nanoPath = Path.of(args[1]), output = Path.of(args[2]);
    if (Files.exists(output)) throw new IllegalArgumentException("Output already exists");
    var json = new GsonBuilder().setPrettyPrinting().create();
    var metadata = JsonParser.parseString(Files.readString(cfrPath.resolve("model.json"))).getAsJsonObject();
    var config = json.fromJson(metadata.get("config"), CfrModelConfig.class);
    NetworkRuntime.initialize();
    var report = new LinkedHashMap<String, Object>();
    report.put("diagnosticOnly", true);
    report.put("timingScope", "Synthetic nonzero FP32 gradients generated by individual parameter sums, with deterministic per-parameter scales. Time includes native flatten/pack/clear, finite validation, CFR norm/clip when applicable, AdamW and parameter publication plus GPU completion. Model load, gradient creation, forward/backward, input preparation and persistence excluded. Nano uses its production ONLINE_ACTOR/ONLINE_VALUE selection and shared two-optimizer path, with the same CFR learning-rate/weight-decay values for diagnosis. This is fixed-cost isolation, not a train/s or quality comparison.");
    report.put("warmup", 8); report.put("repeats", 100);
    var measurements = new ArrayList<Object>(); report.put("measurements", measurements);
    for (String mode : args[3].split(",")) {
      boolean cfr = mode.equals("CFR");
      if (!cfr && !mode.equals("NANO")) throw new IllegalArgumentException("Unknown mode");
      try (Model model = cfr ? loadCfr(cfrPath, config) : EpsilonDecisionCheckpointManager.load(nanoPath, Device.gpu(0), false);
          var execution = new DecisionExecutionContext()) {
        Predicate<String> selected = cfr ? name -> true : EpsilonDecisionNetwork::isOnlineTrainingParameterName;
        long count = 0;
        for (var entry : model.getBlock().getParameters()) {
          boolean included = selected.test(entry.getKey());
          entry.getValue().freeze(!included);
          entry.getValue().getArray().setRequiresGradient(included);
          if (included) count += entry.getValue().getArray().size();
        }
        var lane = new Lane(model, execution);
        try (DataParallelGroup<Lane> group = cfr ? new CfrOptimizerGroup<>(List.of(lane), execution, config.gradientClip()) : new NanoGroup(lane, execution)) {
          group.executeWork(List.of(worker -> {
            try (var scope = worker.manager().newSubManager(); var collector = worker.newGradientCollector()) {
              NDArray objective = null;
              for (var entry : model.getBlock().getParameters()) if (selected.test(entry.getKey())) {
                var sum = entry.getValue().getArray().square().sum().mul(.0001f); sum.attach(scope);
                objective = objective == null ? sum : objective.add(sum); objective.attach(scope);
              }
              collector.backward(objective);
            }
            return true;
          }));
          group.awaitParameterUpdates();
          var actor = optimizer(config); var value = optimizer(config);
          double[] seconds = new double[100];
          for (int step = -8; step < 100; step++) {
            group.clearTrainingGradients();
            group.executeWork(List.of(worker -> {
              try (var scope = worker.manager().newSubManager(); var collector = worker.newGradientCollector()) {
                int ordinal = 1;
                for (var entry : model.getBlock().getParameters()) if (selected.test(entry.getKey())) {
                  try (var sum = entry.getValue().getArray().sum(); var loss = sum.mul(.0001f * ordinal++)) {
                    collector.backward(loss);
                  }
                }
              }
              return true;
            }));
            group.awaitParameterUpdates();
            long start = System.nanoTime();
            if (cfr) group.applyFlattenedOptimizerStep(actor);
            else group.applyFlattenedOnlineOptimizerSteps(actor, 1, value, 1);
            group.awaitParameterUpdates();
            if (step >= 0) seconds[step] = (System.nanoTime() - start) / 1e9;
          }
          var ordered = seconds.clone(); Arrays.sort(ordered);
          var result = new LinkedHashMap<String, Object>();
          result.put("mode", mode); result.put("parameters", count); result.put("seconds", seconds);
          result.put("medianSeconds", ordered[50]); result.put("meanSeconds", Arrays.stream(seconds).average().orElseThrow());
          measurements.add(result); Files.writeString(output, json.toJson(report));
          System.out.println(mode + " parameters=" + count + " medianMs=" + ordered[50] * 1000);
        }
      }
    }
    report.put("complete", true); Files.writeString(output, json.toJson(report));
  }
  private static Optimizer optimizer(CfrModelConfig config) {
    return Optimizer.adamW().optLearningRateTracker(Tracker.fixed(config.learningRate())).optWeightDecays(config.weightDecay()).build();
  }
  private static Model loadCfr(Path path, CfrModelConfig config) throws Exception {
    Model model = Model.newInstance("cfr-optimizer-probe", Device.gpu(0), "PyTorch");
    var network = new CfrNetwork(config); model.setBlock(network);
    network.initialize(model.getNDManager(), DataType.FLOAT32, new Shape(1, 1));
    try (var in = new DataInputStream(new BufferedInputStream(Files.newInputStream(path.resolve("weights.bin"))))) {
      network.loadParameters(model.getNDManager(), in);
    }
    return model;
  }
  private static final class Lane extends DataParallelGroup.Lane {
    Lane(Model model, DecisionExecutionContext execution) { super(model, false, false, execution); }
  }
  private static final class NanoGroup extends DataParallelGroup<Lane> {
    NanoGroup(OptimizerFixedCostProbe.Lane lane, DecisionExecutionContext execution) {
      super(List.of(lane), ParameterScope.ONLINE, null, DataType.FLOAT32, execution,
        (scope, name) -> switch (scope) {
          case ONLINE -> EpsilonDecisionNetwork.isOnlineTrainingParameterName(name);
          case ONLINE_ACTOR -> EpsilonDecisionNetwork.isOnlineActorParameterName(name);
          case ONLINE_VALUE -> EpsilonDecisionNetwork.isValueParameterName(name);
          default -> throw new IllegalArgumentException("Unexpected scope");
        });
      recordParameterReadiness();
    }
  }
}

