package com.epsilon.cfr.model;

import ai.djl.Device;
import ai.djl.Model;
import ai.djl.ndarray.types.DataType;
import ai.djl.ndarray.types.Shape;
import com.epsilon.cfr.data.CfrReplayStore;
import com.epsilon.cfr.data.CfrTrainingRow;
import com.epsilon.cfr.data.LogWeightedReplay;
import com.epsilon.config.settings.DecisionComputePrecision;
import com.epsilon.nano.ai.decision.input.DecisionInputSchema;
import com.epsilon.network.NetworkDevices;
import com.epsilon.network.NetworkRuntime;
import com.epsilon.training.DataParallelGroup;
import com.epsilon.util.SeedMixer;
import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import java.io.BufferedInputStream;
import java.io.DataInputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.SplittableRandom;
import java.util.TreeMap;

/** 保存済みの同じ重み・教師行で、マイクロバッチの上限だけを変えて比較する診断専用実行。 */
public final class CfrNormComparison {
  private static final Gson JSON = new GsonBuilder().setPrettyPrinting().create();

  private record Metadata(
      int version,
      String architecture,
      String inputSchema,
      CfrModel.Role role,
      CfrModelConfig config,
      long updates,
      boolean trainingState) {}

  public static void main(String[] args) throws Exception {
    if (args.length < 3 || args.length > 11)
      throw new IllegalArgumentException(
          "CHECKPOINT REPLAY_DIR OUTPUT [sampling=uniform-distinct]"
              + " [mode=local] [updates=6] [batch=1024] [microA=512] [microB=1024]"
              + " [seed=20261008] [sampleOffset=0]");
    Path checkpoint = Path.of(args[0]).toAbsolutePath();
    Path replayPath = Path.of(args[1]).toAbsolutePath();
    Path output = Path.of(args[2]).toAbsolutePath();
    String sampling = argument(args, 3, "uniform-distinct");
    String mode = argument(args, 4, "local");
    int steps = Integer.parseInt(argument(args, 5, "6"));
    int batch = Integer.parseInt(argument(args, 6, "1024"));
    int microA = Integer.parseInt(argument(args, 7, "512"));
    int microB = Integer.parseInt(argument(args, 8, "1024"));
    long seed = Long.parseLong(argument(args, 9, "20261008"));
    int offset = Integer.parseInt(argument(args, 10, "0"));
    if (!(sampling.equals("weighted") || sampling.equals("uniform-distinct"))
        || !(mode.equals("local") || mode.equals("cumulative"))
        || steps < 1
        || batch < 1
        || microA < 1
        || microB < 1
        || microB > batch
        || offset < 0) throw new IllegalArgumentException("Invalid comparison arguments");
    Metadata metadata =
        JSON.fromJson(Files.readString(checkpoint.resolve("model.json")), Metadata.class);
    if (metadata == null
        || metadata.version() != 3
        || !CfrNetwork.ARCHITECTURE.equals(metadata.architecture())
        || !DecisionInputSchema.fingerprint().equals(metadata.inputSchema())
        || metadata.role() == null
        || metadata.config() == null
        || !metadata.trainingState()
        || metadata.updates() < 0)
      throw new IllegalArgumentException("Expected a current CFR training checkpoint");
    if (metadata.config().computePrecision() != DecisionComputePrecision.BFLOAT16)
      throw new IllegalArgumentException("Expected BFLOAT16 checkpoint for existing BF16 criteria");
    if (microA != microB) throw new IllegalArgumentException("Expected identical microbatch limits");
    Files.createDirectories(output.getParent());
    Files.createDirectory(output);
    NetworkRuntime.initialize();
    Device device = Device.gpu(Integer.getInteger("epsilon.cfr.device", 0));
    var report = new LinkedHashMap<String, Object>();
    report.put("checkpoint", checkpoint.toString());
    report.put("replay", replayPath.toString());
    report.put("role", metadata.role());
    report.put("sourceConfig", metadata.config());
    report.put("sampling", sampling);
    report.put("comparison", "Original repeated max reduction/readback versus reuse of the common validation maximum. Both use the same scalar division, norm and clipping arithmetic. All other learner code and loaded optimizer state are identical.");
    report.put("mode", mode);
    report.put("batch", batch);
    report.put("microA", microA);
    report.put("microB", microB);
    report.put("seed", seed);
    report.put("sampleOffset", offset);
    report.put("criteriaSource", "CfrBatchingTest and CfrMultiplicityLearningTest BF16 criteria");
    report.put(
        "timingScope",
        "Diagnostic train+GPU completion only. Parameter readbacks, optimizer"
            + " synchronization and sampling are outside these times. No throughput conclusion.");
    List<Object> comparisons = new ArrayList<>();
    report.put("steps", comparisons);
    boolean passed = true;
    Path optimizer = output.resolve("comparison-optimizer.bin");
    try (var replay = CfrReplayStore.loadGeneration(replayPath, "performance-benchmark", 1);
        var baseline = new Fixture(checkpoint, metadata, microA, device, true);
        var candidate = new Fixture(checkpoint, metadata, microB, device, false)) {
      var sampler =
          metadata.role() == CfrModel.Role.REGRET
              ? replay.regretSampler()
              : replay.averageSampler();
      report.put("replayWeights", sampler.metrics());
      var original = snapshot(baseline.network);
      requireSame(original, snapshot(candidate.network));
      for (int step = 1; step <= steps; step++) {
        if (mode.equals("local") && step > 1) {
          baseline.learner.saveOptimizer(optimizer);
          candidate.learner.synchronizeParameters();
          DataParallelGroup.copyParameters(baseline.model, candidate.model);
          candidate.learner.loadOptimizer(optimizer);
        }
        var origin = mode.equals("local") ? snapshot(baseline.network) : original;
        if (mode.equals("local")) requireSame(origin, snapshot(candidate.network));
        List<CfrTrainingRow> rows =
            sample(
                sampler,
                sampling,
                batch,
                new SplittableRandom(SeedMixer.derive(seed, 0x44524157L, offset + step - 1)));
        var result = new LinkedHashMap<String, Object>();
        result.put("step", step);
        result.put("sampleUpdate", offset + step - 1);
        result.put("buckets", buckets(rows, microA, microB));
        long start = System.nanoTime();
        var a = baseline.learner.train(rows, metadata.updates() + step);
        baseline.learner.awaitModelReady();
        result.put("microATrainAndAwaitSeconds", (System.nanoTime() - start) / 1e9);
        start = System.nanoTime();
        var b = candidate.learner.train(rows, metadata.updates() + step);
        candidate.learner.awaitModelReady();
        result.put("microBTrainAndAwaitSeconds", (System.nanoTime() - start) / 1e9);
        result.put("microAMetrics", a);
        result.put("microBMetrics", b);
        List<String> failures = new ArrayList<>();
        check(a.samples() == rows.size() && b.samples() == rows.size(), "sample count", failures);
        check(Math.abs(b.loss() - a.loss()) <= 2e-4 + .01 * Math.abs(a.loss()), "loss", failures);
        check(
            Math.abs(b.gradientNorm() - a.gradientNorm()) <= 2e-4 + .02 * a.gradientNorm(),
            "gradientNorm",
            failures);
        var parameters = new Difference();
        var updates = new Difference();
        double stateUpdateSquared = 0;
        double maxElementDifference = 0;
        double elementTolerance =
            .5 * (mode.equals("local") ? 1 : step) * metadata.config().learningRate();
        var wanted = snapshot(baseline.network);
        var actual = snapshot(candidate.network);
        for (var entry : wanted.entrySet()) {
          float[] expected = entry.getValue(), found = actual.get(entry.getKey());
          float[] before = origin.get(entry.getKey());
          parameters.add(found, expected, null);
          updates.add(found, expected, before);
          for (int i = 0; i < found.length; i++) {
            maxElementDifference =
                Math.max(maxElementDifference, Math.abs((double) found[i] - expected[i]));
            if (entry.getKey().contains("stateEncoder")) {
              double change = (double) expected[i] - before[i];
              stateUpdateSquared += change * change;
            }
          }
        }
        check(maxElementDifference <= elementTolerance, "parameter element maximum", failures);
        parameters.check(5e-4, .99999, "parameters", failures);
        updates.check(.03, .999, "AdamW update", failures);
        result.put("lossAbsoluteDifference", Math.abs(b.loss() - a.loss()));
        result.put("gradientNormAbsoluteDifference", Math.abs(b.gradientNorm() - a.gradientNorm()));
        result.put("parameters", parameters.summary());
        result.put("adamWUpdate", updates.summary());
        result.put("stateEncoderUpdateL2", Math.sqrt(stateUpdateSquared));
        result.put("maxElementDifference", maxElementDifference);
        result.put("elementTolerance", elementTolerance);
        result.put("failures", failures);
        result.put("passed", failures.isEmpty());
        comparisons.add(result);
        passed &= failures.isEmpty();
        report.put("passed", passed);
        Files.writeString(output.resolve("result.json"), JSON.toJson(report));
        System.out.println(
            "CFR microbatch comparison role="
                + metadata.role()
                + " mode="
                + mode
                + " sampling="
                + sampling
                + " step="
                + step
                + " passed="
                + failures.isEmpty()
                + " updateRelativeL2="
                + updates.relativeError()
                + " updateCosine="
                + updates.cosine());
      }
    } finally {
      Files.deleteIfExists(optimizer);
    }
    if (!passed)
      throw new AssertionError(
          "Microbatch comparison exceeded existing BF16 criteria; see result.json");
  }

  private static String argument(String[] args, int index, String fallback) {
    return args.length > index ? args[index] : fallback;
  }

  private static List<CfrTrainingRow> sample(
      LogWeightedReplay sampler, String sampling, int count, SplittableRandom random) {
    if (sampling.equals("weighted")) return sampler.sample(count, random);
    if (count > sampler.size()) throw new IllegalArgumentException("Too few distinct replay rows");
    Map<Integer, Integer> positions = new HashMap<>();
    List<CfrTrainingRow> rows = new ArrayList<>(count);
    for (int picked = 0; picked < count; picked++) {
      int last = sampler.size() - picked - 1;
      int selected = random.nextInt(last + 1);
      int index = positions.getOrDefault(selected, selected);
      if (selected != last) positions.put(selected, positions.getOrDefault(last, last));
      positions.remove(last);
      rows.add(sampler.rowAt(index));
    }
    return List.copyOf(rows);
  }

  private static Map<String, Object> buckets(List<CfrTrainingRow> rows, int microA, int microB) {
    Map<String, Integer> counts = new TreeMap<>();
    for (var entry : CfrSampleMultiplicity.aggregate(rows)) {
      var bucket = CfrObservationCodec.decode(entry.row().observation()).host().bucket();
      counts.merge(
          bucket.legalActionCapacity() + "x" + bucket.actionTransitionCapacity(), 1, Integer::sum);
    }
    Map<String, Object> result = new TreeMap<>();
    counts.forEach(
        (key, count) ->
            result.put(
                key,
                Map.of(
                    "uniqueRows",
                    count,
                    "microASizes",
                    sizes(count, microA),
                    "microBSizes",
                    sizes(count, microB))));
    return result;
  }

  private static List<Integer> sizes(int count, int micro) {
    List<Integer> sizes = new ArrayList<>();
    for (int from = 0; from < count; from += micro) sizes.add(Math.min(count - from, micro));
    return sizes;
  }

  private static Map<String, float[]> snapshot(CfrNetwork network) {
    Map<String, float[]> values = new LinkedHashMap<>();
    for (var entry : network.getParameters())
      values.put(entry.getKey(), entry.getValue().getArray().toFloatArray());
    return values;
  }

  private static void requireSame(Map<String, float[]> expected, Map<String, float[]> actual) {
    if (!expected.keySet().equals(actual.keySet()))
      throw new AssertionError("Parameter names differ");
    for (var entry : expected.entrySet())
      if (!java.util.Arrays.equals(entry.getValue(), actual.get(entry.getKey())))
        throw new AssertionError("Comparison starts from different parameters: " + entry.getKey());
  }

  private static void check(boolean value, String message, List<String> failures) {
    if (!value) failures.add(message);
  }

  private static final class Difference {
    double squaredError, squaredActual, squaredExpected, dot;

    void add(float[] actual, float[] expected, float[] origin) {
      if (actual.length != expected.length) throw new AssertionError("Parameter shape differs");
      for (int index = 0; index < actual.length; index++) {
        double initial = origin == null ? 0 : origin[index];
        double a = actual[index] - initial, b = expected[index] - initial;
        squaredError += (a - b) * (a - b);
        squaredActual += a * a;
        squaredExpected += b * b;
        dot += a * b;
      }
    }

    double relativeError() {
      return Math.sqrt(squaredError / Math.max(1e-30, squaredExpected));
    }

    double cosine() {
      return dot / Math.sqrt(squaredActual * squaredExpected);
    }

    void check(
        double relativeTolerance, double minimumCosine, String label, List<String> failures) {
      CfrNormComparison.check(
          relativeError() <= relativeTolerance, label + " relativeL2", failures);
      CfrNormComparison.check(cosine() >= minimumCosine, label + " cosine", failures);
    }

    Map<String, Object> summary() {
      var result = new LinkedHashMap<String, Object>();
      result.put("relativeL2", relativeError());
      result.put("cosine", Double.isFinite(cosine()) ? cosine() : null);
      result.put("absoluteL2", Math.sqrt(squaredError));
      result.put("microAL2", Math.sqrt(squaredExpected));
      result.put("microBL2", Math.sqrt(squaredActual));
      return result;
    }
  }

  private static final class Fixture implements AutoCloseable {
    final Model model;
    final CfrNetwork network;
    final Learner learner;

    Fixture(Path checkpoint, Metadata metadata, int micro, Device device, boolean reference) throws Exception {
      var source = metadata.config();
      var config =
          new CfrModelConfig(
              source.hiddenSize(),
              micro,
              source.learningRate(),
              source.weightDecay(),
              source.gradientClip(),
              source.seed(),
              source.inferenceBatchSize(),
              source.computePrecision(),
              source.tensorTransfer(),
              source.utilityProfile());
      model = Model.newInstance("cfr-microbatch-comparison", device, "PyTorch");
      network = new CfrNetwork(config);
      model.setBlock(network);
      network.initialize(model.getNDManager(), DataType.FLOAT32, new Shape(1, 1));
      try (var input =
          new DataInputStream(
              new BufferedInputStream(Files.newInputStream(checkpoint.resolve("weights.bin"))))) {
        network.loadParameters(model.getNDManager(), input);
        if (input.read() != -1) throw new IllegalArgumentException("Trailing CFR weights");
      }
      for (var parameter : network.getParameters().values()) {
        parameter.freeze(false);
        parameter.getArray().setRequiresGradient(true);
      }
      learner = new Learner(reference, config, metadata.role(), model, network, device);
      learner.loadOptimizer(checkpoint.resolve("optimizer.bin"));
    }

    @Override
    public void close() {
      learner.close();
      model.close();
    }
  }
  private static final class Learner implements AutoCloseable {
    private final CfrLearner candidate;
    private final CfrReferenceLearner reference;
    Learner(boolean useReference, CfrModelConfig config, CfrModel.Role role, Model model, CfrNetwork network, Device device) {
      reference = useReference ? new CfrReferenceLearner(config, role, model, network, NetworkDevices.of(device)) : null;
      candidate = useReference ? null : new CfrLearner(config, role, model, network, NetworkDevices.of(device));
    }
    CfrModel.TrainingMetrics train(List<CfrTrainingRow> rows, long update) { return reference != null ? reference.train(rows, update) : candidate.train(rows, update); }
    void awaitModelReady() { if(reference != null) reference.awaitModelReady(); else candidate.awaitModelReady(); }
    void saveOptimizer(Path path) throws java.io.IOException { if(reference != null) reference.saveOptimizer(path); else candidate.saveOptimizer(path); }
    void loadOptimizer(Path path) throws java.io.IOException { if(reference != null) reference.loadOptimizer(path); else candidate.loadOptimizer(path); }
    void synchronizeParameters() { if(reference != null) reference.synchronizeParameters(); else candidate.synchronizeParameters(); }
    public void close() { if(reference != null) reference.close(); else candidate.close(); }
  }

}

package com.epsilon.cfr.model;

import ai.djl.Device;
import ai.djl.Model;
import ai.djl.engine.Autocast;
import ai.djl.ndarray.NDArray;
import ai.djl.ndarray.NDManager;
import ai.djl.ndarray.types.DataType;
import ai.djl.ndarray.types.Shape;
import ai.djl.training.ParameterStore;
import ai.djl.training.optimizer.Optimizer;
import ai.djl.training.tracker.Tracker;
import com.epsilon.cfr.data.CfrTrainingRow;
import com.epsilon.nano.ai.decision.input.DecisionBatchTransfer;
import com.epsilon.nano.ai.decision.input.DecisionBucket;
import com.epsilon.nano.ai.decision.runtime.EpsilonDecisionAutocast;
import com.epsilon.network.NetworkDevices;
import com.epsilon.runtime.DecisionExecutionContext;
import com.epsilon.training.DataParallelGroup;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Objects;

/**
 * LCFRの回帰損失をNanoと同じ学習実行基盤へ接続する。
 *
 * <p>ワーカー、GPUストリーム、勾配集約、AdamWの一括更新、パラメーター配布は {@link DataParallelGroup}
 * が管理する。ここではLCFRの教師データと入力の対応だけを定義する。
 */
final class CfrReferenceLearner implements AutoCloseable {
  private final CfrModelConfig config;
  private final CfrModel.Role role;
  private final Model canonical;
  private final CfrNetwork network;
  private final NetworkDevices devices;
  private final Optimizer optimizer;
  private final DecisionExecutionContext execution = new DecisionExecutionContext();
  private final CfrObservationCache observations = new CfrObservationCache();
  private CfrReferenceOptimizerGroup<Lane> parallel;
  private boolean pendingUpdates;
  private boolean closed;

  CfrReferenceLearner(
      CfrModelConfig config,
      CfrModel.Role role,
      Model canonical,
      CfrNetwork network,
      NetworkDevices devices) {
    this.config = Objects.requireNonNull(config);
    this.role = Objects.requireNonNull(role);
    this.canonical = Objects.requireNonNull(canonical);
    this.network = Objects.requireNonNull(network);
    if (devices == null || !canonical.getNDManager().getDevice().equals(devices.primary())) {
      throw new IllegalArgumentException("Canonical CFR model must use the first learner device");
    }
    var unique = new HashSet<Device>();
    for (Device device : devices) {
      if (!unique.add(Objects.requireNonNull(device)))
        throw new IllegalArgumentException("Duplicate learner device");
    }
    this.devices = devices;
    optimizer =
        Optimizer.adamW()
            .optLearningRateTracker(Tracker.fixed(config.learningRate()))
            .optWeightDecays(config.weightDecay())
            .build();
  }

  CfrModel.TrainingMetrics train(List<CfrTrainingRow> rows, long nextUpdate) {
    ensureOpen();
    if (rows.isEmpty() || nextUpdate < 1) throw new IllegalArgumentException("Invalid CFR update");
    List<List<List<Input>>> assignments = assign(rows);
    CfrReferenceOptimizerGroup<Lane> group = parallel();
    List<Integer> active = new ArrayList<>();
    List<DataParallelGroup.LaneWork<Lane, Double>> work = new ArrayList<>();
    for (int lane = 0; lane < assignments.size(); lane++) {
      List<List<Input>> batches = assignments.get(lane);
      if (batches.isEmpty()) continue;
      active.add(lane);
      work.add(worker -> backward(worker, batches, rows.size()));
    }
    int[] lanes = active.stream().mapToInt(Integer::intValue).toArray();
    group.setActiveGradientLanes(lanes);
    try {
      double loss =
          group.executeAssigned(lanes, work).stream().mapToDouble(Double::doubleValue).sum();
      if (!Double.isFinite(loss)) throw new IllegalStateException("Nonfinite CFR objective");
      group.applyFlattenedOptimizerStep(optimizer);
      pendingUpdates = true;
      return new CfrModel.TrainingMetrics(rows.size(), loss, group.gradientNorm(), nextUpdate);
    } catch (IOException failure) {
      clearFailedStep(group, failure);
      throw new UncheckedIOException("CFR learner execution failed", failure);
    } catch (RuntimeException | Error failure) {
      clearFailedStep(group, failure);
      throw failure;
    }
  }

  private static void clearFailedStep(CfrReferenceOptimizerGroup<?> group, Throwable failure) {
    try {
      group.clearTrainingGradients();
    } catch (RuntimeException | Error cleanupFailure) {
      failure.addSuppressed(cleanupFailure);
    }
  }

  private List<List<List<Input>>> assign(List<CfrTrainingRow> rows) {
    List<Input> inputs = new ArrayList<>();
    for (var entry : CfrSampleMultiplicity.aggregate(rows)) {
      CfrTrainingRow row = entry.row();
      var observation = observations.get(row);
      var host = observation.host();
      int[] actions = row.legalActionIds();
      if (host.legalActionCount(0) != actions.length)
        throw new IllegalArgumentException("CFR target action count mismatch");
      for (int action = 0; action < actions.length; action++) {
        if (host.legalActionId(0, action) != actions[action])
          throw new IllegalArgumentException("CFR target action order mismatch");
      }
      inputs.add(new Input(row, observation, entry.count()));
    }
    List<List<List<Input>>> assignments = new ArrayList<>(devices.size());
    for (int lane = 0; lane < devices.size(); lane++) assignments.add(new ArrayList<>());
    List<List<Input>> batches = new ArrayList<>();
    var buckets = new LinkedHashMap<DecisionBucket, List<Input>>();
    for (Input input : inputs)
      buckets
          .computeIfAbsent(input.observation().host().bucket(), ignored -> new ArrayList<>())
          .add(input);
    // 重複集約前の抽選数から分割上限を決め、複数デバイスへの割り当ての偏りを抑える。
    int microBatchSize =
        Math.min(config.microBatchSize(), Math.ceilDiv(rows.size(), devices.size()));
    for (List<Input> bucket : buckets.values()) {
      for (int from = 0; from < bucket.size(); from += microBatchSize)
        batches.add(bucket.subList(from, Math.min(bucket.size(), from + microBatchSize)));
    }
    // 候補の容量区分を揃え、重いバッチから負荷の少ないデバイスへ割り当てる。
    batches.sort(Comparator.comparingLong(CfrReferenceLearner::estimatedWork).reversed());
    long[] work = new long[devices.size()];
    for (List<Input> batch : batches) {
      int lane = 0;
      for (int candidate = 1; candidate < work.length; candidate++)
        if (work[candidate] < work[lane]) lane = candidate;
      assignments.get(lane).add(batch);
      work[lane] += estimatedWork(batch);
    }
    return assignments;
  }

  private static long estimatedWork(List<Input> batch) {
    var bucket = batch.getFirst().observation().host().bucket();
    return batch.size()
        * (128L + (long) bucket.legalActionCapacity() * bucket.actionTransitionCapacity());
  }

  private double backward(Lane lane, List<List<Input>> batches, int totalRows) {
    double objective = 0;
    for (List<Input> part : batches) {
      try (NDManager scope = lane.manager().newSubManager();
          var collector = lane.newGradientCollector()) {
        var store = new ParameterStore(scope, true);
        NDArray loss = batchLoss(lane, scope, store, part, totalRows);
        float value;
        if (scope.getDevice().isGpu()) {
          // Nanoと同じく損失値の回収を逆伝播より先に予約し、ホスト側で逆伝播全体の完了を待たずに済むようにする。
          try (NDArray metric = loss.reshape(1)) {
            try {
              lane.enqueueMetricReadback(metric);
              collector.backward(loss);
              value = lane.awaitMetricReadback()[0];
            } finally {
              lane.closeMetricReadback();
            }
          }
        } else {
          collector.backward(loss);
          value = loss.getFloat();
        }
        if (!Float.isFinite(value)) throw new IllegalStateException("Nonfinite CFR objective");
        objective += value;
      }
    }
    return objective;
  }

  private NDArray batchLoss(
      Lane lane, NDManager scope, ParameterStore store, List<Input> part, int totalRows) {
    var observations = part.stream().map(Input::observation).toList();
    var host = CfrObservationCodec.batch(observations);
    var batch =
        DecisionBatchTransfer.transferTrainingToDevice(
            scope, host.sliceRows(0, host.size()), lane.transfer(), config.tensorTransfer());
    int capacity = host.bucket().legalActionCapacity();
    float[] targets = new float[Math.multiplyExact(part.size(), capacity)];
    float[] multiplicities = new float[part.size()];
    for (int row = 0; row < part.size(); row++) {
      Input input = part.get(row);
      multiplicities[row] = input.count();
      double[] teacher =
          role == CfrModel.Role.REGRET ? input.row().regretTargets() : input.row().targetPolicy();
      for (int action = 0; action < teacher.length; action++) {
        float value = (float) teacher[action];
        if (!Float.isFinite(value))
          throw new IllegalArgumentException("Unrepresentable CFR teacher");
        targets[row * capacity + action] = value;
      }
    }
    NDArray target = scope.create(targets, new Shape(part.size(), capacity));
    NDArray multiplicity = scope.create(multiplicities, new Shape(part.size(), 1));
    NDArray scores;
    try (Autocast ignored =
        EpsilonDecisionAutocast.open(scope, config.precision(scope.getDevice()))) {
      scores = lane.network.scores(store, batch, true);
    }
    // 順伝播だけを混合精度で計算し、損失はFP32にする。toTypeで勾配を切らず、Nanoと同じ型昇格を使う。
    if (scores.getDataType() != DataType.FLOAT32)
      scores = scores.add(scope.zeros(new Shape(1), DataType.FLOAT32));
    NDArray mask = batch.legalActionMask().toType(DataType.FLOAT32, false);
    return objective(role, scores, target, mask, multiplicity, totalRows);
  }

  /** 抽出済みの出現回数だけを掛け、分母には全デバイスで共通の集約前の行数を使う。 */
  static NDArray objective(
      CfrModel.Role role,
      NDArray scores,
      NDArray target,
      NDArray mask,
      NDArray multiplicity,
      int totalRows) {
    return role == CfrModel.Role.REGRET
        ? scores.sub(target).square().mul(mask).mul(multiplicity).sum().div(totalRows)
        : scores
            .add(mask.neg().add(1).mul(-1e9f))
            .logSoftmax(1)
            .mul(target)
            .mul(multiplicity)
            .sum()
            .neg()
            .div(totalRows);
  }

  void saveOptimizer(Path path) throws IOException {
    ensureOpen();
    awaitModelReady();
    optimizer.saveState(path);
  }

  /** 学習とは別のストリームでの保存・推論・複製に先立つ一度だけの完了待ち。 */
  void awaitModelReady() {
    ensureOpen();
    if (pendingUpdates) {
      parallel.awaitParameterUpdates();
      pendingUpdates = false;
    }
  }

  void loadOptimizer(Path path) throws IOException {
    ensureOpen();
    optimizer.loadState(canonical.getNDManager(), path);
  }

  /** パラメーターを外から復元した後は、次の更新時に共通基盤の連続バッファも構築し直す。 */
  void synchronizeParameters() {
    ensureOpen();
    awaitModelReady();
    if (parallel != null) {
      parallel.close();
      parallel = null;
    }
  }

  int deviceCount() {
    return devices.size();
  }

  private CfrReferenceOptimizerGroup<Lane> parallel() {
    if (parallel != null) return parallel;
    var lanes = new ArrayList<Lane>();
    CfrReferenceOptimizerGroup<Lane> created = null;
    try {
      lanes.add(new Lane(canonical, network, false, execution));
      for (int index = 1; index < devices.size(); index++) {
        Model replica = Model.newInstance("epsilon-cfr-learner", devices.get(index), "PyTorch");
        try {
          CfrNetwork replicaNetwork = new CfrNetwork(config);
          replica.setBlock(replicaNetwork);
          replicaNetwork.initialize(replica.getNDManager(), DataType.FLOAT32, new Shape(1, 1));
          DataParallelGroup.copyParameters(canonical, replica);
          lanes.add(new Lane(replica, replicaNetwork, true, execution));
        } catch (RuntimeException | Error failure) {
          replica.close();
          throw failure;
        }
      }
      created = new CfrReferenceOptimizerGroup<>(lanes, execution, config.gradientClip());
      // 成功した更新の勾配は共通のpackAndClearで消去する。途中で失敗した際の部分勾配だけ別途破棄する。
      created.clearTrainingGradients();
      parallel = created;
      return created;
    } catch (RuntimeException | Error failure) {
      if (created != null) {
        try {
          created.close();
        } catch (RuntimeException closeFailure) {
          failure.addSuppressed(closeFailure);
        }
      } else {
        for (Lane lane : lanes) {
          try {
            lane.close();
          } catch (RuntimeException closeFailure) {
            failure.addSuppressed(closeFailure);
          }
        }
      }
      throw failure;
    }
  }

  private void ensureOpen() {
    if (closed) throw new IllegalStateException("CFR learner is closed");
  }

  @Override
  public void close() {
    if (closed) return;
    closed = true;
    try {
      if (parallel != null) parallel.close();
    } finally {
      try {
        observations.close();
      } finally {
        execution.close();
      }
    }
  }

  private record Input(CfrTrainingRow row, CfrObservationCodec.Decoded observation, int count) {}

  private static final class Lane extends DataParallelGroup.Lane {
    private final CfrNetwork network;
    private DecisionBatchTransfer.Workspace transfer;

    Lane(Model model, CfrNetwork network, boolean ownsModel, DecisionExecutionContext execution) {
      super(model, ownsModel, false, execution);
      this.network = network;
    }

    DecisionBatchTransfer.Workspace transfer() {
      if (transfer == null) transfer = new DecisionBatchTransfer.Workspace(manager());
      return transfer;
    }

    @Override
    public void close() {
      try {
        if (transfer != null) transfer.close();
      } finally {
        super.close();
      }
    }
  }
}

package com.epsilon.cfr.model;

import ai.djl.ndarray.NDArray;
import ai.djl.ndarray.NDManager;
import ai.djl.ndarray.types.DataType;
import com.epsilon.runtime.DecisionExecutionContext;
import com.epsilon.training.DataParallelGroup;
import java.util.List;

/** 方策とスカラー基準値の学習で共有する、FP32の連続バッファを使ったAdamWの勾配準備処理。 */
final class CfrReferenceOptimizerGroup<L extends DataParallelGroup.Lane> extends DataParallelGroup<L> {
  private final float gradientClip;
  private double gradientNorm;

  CfrReferenceOptimizerGroup(List<L> lanes, DecisionExecutionContext execution, float gradientClip) {
    super(lanes, ParameterScope.ALL, null, DataType.FLOAT32, execution, (scope, name) -> true);
    this.gradientClip = gradientClip;
    recordParameterReadiness();
  }

  double gradientNorm() {
    return gradientNorm;
  }

  @Override
  protected boolean allowsZeroGradientUpdates() {
    return true;
  }

  @Override
  protected void prepareOptimizerGradient(ParameterScope scope, NDArray gradient, float ignoredMaximum, double ignoredScale) {
    try (NDManager temporary = gradient.getManager().newSubManager()) {
      NDArray absolute = gradient.abs();
      absolute.attach(temporary);
      NDArray maximum = absolute.max();
      maximum.attach(temporary);
      double max = maximum.getFloat();
      if (max == 0) {
        gradientNorm = 0;
        return;
      }
      NDArray scaled = gradient.div(max);
      scaled.attach(temporary);
      NDArray squared = scaled.square();
      squared.attach(temporary);
      NDArray sum = squared.sum();
      sum.attach(temporary);
      gradientNorm = max * Math.sqrt(sum.getFloat());
      if (!Double.isFinite(gradientNorm))
        throw new IllegalStateException("Nonfinite CFR gradient norm");
      if (gradientClip > 0 && gradientNorm > gradientClip)
        gradient.muli(gradientClip / gradientNorm);
    }
  }
}

