package com.epsilon.cfr.model;

import ai.djl.Device;
import ai.djl.Model;
import ai.djl.engine.Engine;
import ai.djl.ndarray.NDArray;
import ai.djl.ndarray.types.DataType;
import ai.djl.ndarray.types.Shape;
import ai.djl.nn.core.Linear;
import com.epsilon.network.NetworkRuntime;
import com.epsilon.runtime.DecisionExecutionContext;
import com.epsilon.training.DataParallelGroup;
import java.util.List;
import org.testng.Assert;
import org.testng.SkipException;
import org.testng.annotations.Test;

/** ゼロ・極小・大きい勾配も、クリップ前ノルムとクリップ後の方向を保つことを検証する。 */
public class CfrGradientNormTest {
  @Test(groups = "native")
  public void stableNormAndClippingPreserveReferenceOnCpu() {
    verify(Device.cpu());
  }

  @Test(groups = "rocm")
  public void stableNormAndClippingPreserveReferenceOnGpu() {
    NetworkRuntime.initialize();
    if (Engine.getInstance().getGpuCount() == 0) throw new SkipException("GPU required");
    verify(Device.gpu());
  }

  private static void verify(Device device) {
    NetworkRuntime.initialize();
    float[][] values = {
      {0, -0f, 0, 0},
      {3, 4, -12, 0},
      {Float.MIN_NORMAL, -2 * Float.MIN_NORMAL, 4 * Float.MIN_NORMAL, 0},
      {Float.MAX_VALUE / 2, -Float.MAX_VALUE / 4, Float.MAX_VALUE / 8, 0},
      {.00017f, -.25f, .99999f, -32.3f}
    };
    for (float clip : new float[] {0, .5f, 100}) {
      try (Model model = Model.newInstance("cfr-gradient-norm-test", device, "PyTorch");
          var execution = new DecisionExecutionContext()) {
        var block = Linear.builder().setUnits(1).build();
        model.setBlock(block);
        block.initialize(model.getNDManager(), DataType.FLOAT32, new Shape(1, 4));
        try (var group =
            new CfrOptimizerGroup<>(List.of(new Lane(model, execution)), execution, clip)) {
          for (float[] source : values) {
            try (var scope = model.getNDManager().newSubManager()) {
              NDArray actual = scope.create(source);
              NDArray expected = scope.create(source);
              double reference = reference(expected, clip);
              group.prepareOptimizerGradient(DataParallelGroup.ParameterScope.ALL, actual);
              Assert.assertEquals(group.gradientNorm(), reference, 0d);
              Assert.assertEquals(actual.toFloatArray(), expected.toFloatArray());
              double exact = 0;
              for (float value : source) exact = Math.hypot(exact, value);
              Assert.assertEquals(
                  group.gradientNorm(), exact, Math.max(Double.MIN_NORMAL, exact * 1e-7));
            }
          }
          for (float invalid :
              new float[] {Float.NaN, Float.POSITIVE_INFINITY, Float.NEGATIVE_INFINITY}) {
            try (var scope = model.getNDManager().newSubManager()) {
              NDArray gradient = scope.create(new float[] {1, invalid, 0, 0});
              Assert.expectThrows(
                  IllegalStateException.class,
                  () ->
                      group.prepareOptimizerGradient(
                          DataParallelGroup.ParameterScope.ALL, gradient));
            }
          }
        }
      }
    }
  }

  private static double reference(NDArray gradient, float clip) {
    double maximum = gradient.abs().max().getFloat();
    if (maximum == 0) return 0;
    double norm = maximum * Math.sqrt(gradient.div(maximum).square().sum().getFloat());
    if (clip > 0 && norm > clip) gradient.muli(clip / norm);
    return norm;
  }

  private static final class Lane extends DataParallelGroup.Lane {
    Lane(Model model, DecisionExecutionContext execution) {
      super(model, false, false, execution);
    }
  }
}

