package com.epsilon.cfr.data;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.SplittableRandom;
import java.util.concurrent.atomic.AtomicInteger;
import org.testng.Assert;
import org.testng.annotations.Test;

/** 一括抽出で読み込みをまとめても、抽選列・教師値・変更不可の所有権が維持されることを検証する。 */
public class LogWeightedReplayBatchTest {
  @Test
  public void batchMatchesScalarDrawsAndLoadsEachSelectedIndexOnce() {
    double[][] weights = {
      {0, 0, 0, 0, 0},
      {0, -1, -5, -1000, Double.NEGATIVE_INFINITY},
      {1e308, 1e308, Double.NEGATIVE_INFINITY, 1e308, 1e308}
    };
    for (double[] distribution : weights) {
      var source = new ArrayList<CfrTrainingRow>();
      for (int index = 0; index < distribution.length; index++)
        source.add(row(index, distribution[index]));
      var scalar = new LogWeightedReplay(source, CfrTrainingRow::logRegretWeight);
      var loads = new AtomicInteger();
      var batchSampler =
          new LogWeightedReplay(
              source.size(),
              index -> source.get(index).logRegretWeight(),
              index -> {
                loads.incrementAndGet();
                return copy(source.get(index));
              });
      var scalarRandom = new SplittableRandom(20261008);
      var batchRandom = new SplittableRandom(20261008);
      List<CfrTrainingRow> actual = batchSampler.sample(1024, batchRandom);
      var firstById = new HashMap<CfrSampleId, CfrTrainingRow>();
      for (CfrTrainingRow found : actual) {
        CfrTrainingRow expected = scalar.sample(scalarRandom);
        Assert.assertTrue(found.contentEquals(expected), expected.id().toString());
        Assert.assertEquals(found.regretTargets(), expected.regretTargets());
        var first = firstById.putIfAbsent(found.id(), found);
        if (first != null) Assert.assertSame(found, first);
        found.legalActionIds()[0] = 99;
        found.targetPolicy()[0] = 99;
        found.explicitRegretTargets()[0] = 99;
        found.observation().toByteArray()[0] = 99;
        Assert.assertTrue(found.contentEquals(expected), "Returned arrays must remain independent");
      }
      Assert.assertEquals(batchRandom.nextLong(), scalarRandom.nextLong(), "Random consumption");
      Assert.assertEquals(
          loads.get(), firstById.size(), "Only selected distinct indices are loaded");
      Assert.assertTrue(loads.get() < actual.size());
    }
  }

  @Test
  public void subsequentBatchReloadsRowsAndEmptyBatchDoesNotReadOrDraw() {
    var revision = new AtomicInteger();
    var sampler = new LogWeightedReplay(1, ignored -> 0, ignored -> row(revision.get(), 0));
    var random = new SplittableRandom(11);
    var untouched = new SplittableRandom(11);
    Assert.assertTrue(sampler.sample(0, random).isEmpty());
    Assert.assertEquals(random.nextLong(), untouched.nextLong());
    var first = sampler.sample(4, random);
    revision.incrementAndGet();
    var second = sampler.sample(4, random);
    Assert.assertEquals(first.getFirst().id().episodeId(), 0);
    Assert.assertEquals(second.getFirst().id().episodeId(), 1);
    Assert.assertNotSame(first.getFirst(), second.getFirst());
  }

  private static CfrTrainingRow row(int index, double weight) {
    return new CfrTrainingRow(
        new CfrSampleId(1, index, 3, index % 4),
        new int[] {2, 3},
        1,
        new double[] {.3, .7},
        -.25 + index * .1,
        weight,
        weight,
        new byte[] {(byte) index, 2, 3},
        new double[] {-.1 - index, .3 + index});
  }

  private static CfrTrainingRow copy(CfrTrainingRow row) {
    return new CfrTrainingRow(
        row.id(),
        row.legalActionIds(),
        row.selectedSlot(),
        row.targetPolicy(),
        row.utility(),
        row.logRegretWeight(),
        row.logAverageWeight(),
        row.observation(),
        row.explicitRegretTargets());
  }
}
